class Solution {
    public String countOfAtoms(String formula){
        Deque<Map<String,Integer>> stack=new ArrayDeque<>();
        stack.addLast(new HashMap<>());
        int index=0;
        while(index<formula.length()){
            char c=formula.charAt(index);
            if(c=='('){
                stack.addLast(new HashMap<>());
                index++;
            }else if(c==')'){
                index++;
                int start=index;
                while(index<formula.length()&&Character.isDigit(formula.charAt(index)))index++;
                int multiplier=start==index?1:Integer.parseInt(formula.substring(start,index));
                Map<String,Integer> group=stack.removeLast(),parent=stack.peekLast();
                for(Map.Entry<String,Integer> entry:group.entrySet())parent.put(entry.getKey(),parent.getOrDefault(entry.getKey(),0)+entry.getValue()*multiplier);
            }else{
                int start=index++;
                while(index<formula.length()&&Character.isLowerCase(formula.charAt(index)))index++;
                String atom=formula.substring(start,index);
                start=index;
                while(index<formula.length()&&Character.isDigit(formula.charAt(index)))index++;
                int count=start==index?1:Integer.parseInt(formula.substring(start,index));
                Map<String,Integer> current=stack.peekLast();
                current.put(atom,current.getOrDefault(atom,0)+count);
            }
        }
        StringBuilder answer=new StringBuilder();
        for(Map.Entry<String,Integer> entry:new TreeMap<>(stack.peekLast()).entrySet()){
            answer.append(entry.getKey());
            if(entry.getValue()>1)answer.append(entry.getValue());
        }
        return answer.toString();
    }
}

code.kotlin:
class Solution {
    fun countOfAtoms(formula:String):String{
        val stack=java.util.ArrayDeque<MutableMap<String,Int>>();
        stack.addLast(hashMapOf());
        var index=0;
        while(index<formula.length){
            when(formula[index]){
                '('->{
                    stack.addLast(hashMapOf());
                    index++
                };
                ')'->{
                    index++;
                    val start=index;
                    while(index<formula.length&&formula[index].isDigit())index++;
                    val multiplier=if(start==index)1 else formula.substring(start,index).toInt();
                    val group=stack.removeLast();
                    val parent=stack.peekLast();
                    for((atom,count) in group)parent[atom]=(parent[atom]?:0)+count*multiplier
                };
                else->{
                    val start=index++;
                    while(index<formula.length&&formula[index].isLowerCase())index++;
                    val atom=formula.substring(start,index);
                    val numberStart=index;
                    while(index<formula.length&&formula[index].isDigit())index++;
                    val count=if(numberStart==index)1 else formula.substring(numberStart,index).toInt();
                    val current=stack.peekLast();
                    current[atom]=(current[atom]?:0)+count
                }
            }
        };
        return stack.peekLast().toSortedMap().entries.joinToString(""){
            (atom,count)->atom+if(count>1)count else ""
        }
    }
}

